import React, { useState, useEffect } from "react";

// HOC: Wraps a component and shows animated "Loading..." text
const withLoadingAnimation = (WrappedComponent, loadingText = "Loading...") => {
    return function LoadingWrapper({ loading, ...props }) {
        const [displayText, setDisplayText] = useState("");
        const [index, setIndex] = useState(0);

        useEffect(() => {
            if (!loading) {
                setDisplayText("");
                setIndex(0);
                return;
            }

            const interval = setInterval(() => {
                setDisplayText((prev) => prev + loadingText[index]);
                setIndex((prev) => {
                    if (prev + 1 >= loadingText.length) {
                        // Reset after full string displayed
                        setDisplayText("");
                        return 0;
                    }
                    return prev + 1;
                });
            }, 200); // 200ms per letter, adjust speed here

            return () => clearInterval(interval);
        }, [loading, index, loadingText]);

        if (loading) {
            return (
                <div style={{ fontSize: "18px", fontWeight: "bold", textAlign: "center", margin: "40px 0" }}>
                    {displayText}
                </div>
            );
        }

        return <WrappedComponent {...props} />;
    };
};

export default withLoadingAnimation;
